"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["13022"],{4762(e){e.exports=JSON.parse('{"id":"FIN-1238","slug":"classical-economics","term":"Classical Economics","also_known_as":[],"difficulty":"Advanced","definition":"Classical economics is a school of economic thought, developed in the late eighteenth and nineteenth centuries, which holds that free markets tend to reach full employment on their own, with flexible prices and wages balancing supply and demand.","explanation":["Classical economists, including Adam Smith, David Ricardo, Thomas Malthus and John Stuart Mill, laid the foundations of modern economics. Smith\'s 1776 book The Wealth of Nations described how individuals pursuing their own interests in competitive markets can benefit society, an idea often summarised as the invisible hand.","Key classical ideas include the benefits of specialization and free trade, the role of competition in setting prices, and the belief that markets are self-correcting. If there is unemployment, wages fall until employers hire the available workers. Government intervention in the economy should therefore be limited.","For example, a classical economist would expect a fall in demand to lead to lower prices and wages, restoring full employment without government action.","Classical economics was challenged by the Great Depression, which led to Keynesian economics. Many classical ideas were later revived and developed in new classical and other market-oriented schools of thought."],"note":"","total":1500,"prev":{"slug":"claims","term":"Claims"},"next":{"slug":"clawback","term":"Clawback"}}')}}]);